        $refreshToken = $this->redeemCodeWithAudience(self::CLIENT_ID)['refresh_token'];

        $statuses = [$this->refreshStatus($refreshToken), $this->refreshStatus($refreshToken)];

        $this->assertSame([200, 400], $statuses);
